/**
 * 「谁说了什么」——把会话里一批批收下来的话，投影给房间页读。
 *
 * **为什么要注册一个事件消费者**：房间页要显示"这一轮谁说了什么"，而那句话是**宿主 append
 * 的会话事件**。浏览器半边没有别的口子能读到它——`shell.overlay` 是帧级的、`conversation.view`
 * 的 owner props 里没有消息。所以唯一的办法是注册一个 `ConversationNodeDefinition`，把事件折成
 * 投影，再从座位里读投影。
 *
 * **投影的 key 就是 `kind`**（`'jubensha-said'`）——读它时用同一个名字，没有单独的注册步骤。
 *
 * **`visibility: 'hidden'`**：投影进得来、对话流里不出现。房间页有自己的渲染，不必在对话流里
 * 再插一行。
 *
 * **match `agent/inbox/spliced`**：它的 `data.inserted[]` 就是一批完整消息，所以不必去拼
 * `user/message`。而 `source.kind` 是分辨"谁说的"那个字段——真人是 `user`，注入是
 * `runtime-context` / `skill-catalog` / `time-context`，别的插件是 `plugin:<名字>`。
 *
 * @module @max-null/dsh-jubensha/client/said
 */
import type { ConversationNodeDefinition } from '@deepseek-ai/dsh-client-ui-conversation/client'
import type { ChatNode, ChatSnapshot } from '@deepseek-ai/dsh-client-ui-chat/client'

/** 投影的名字。读它时用同一个字符串。 */
export const SAID_KIND = 'jubensha-said'

/** 一句话。 */
export interface SaidLine {
  /** 它来自哪个事件——排序与去重都用它。 */
  readonly seq: number
  /** 谁说的（`source.kind`）。 */
  readonly from: string
  /**
   * Team 消息信封里那个发信人，形如 `p1-m3k8f2a`（座位 + 时间戳 + 随机后缀，见宿主的
   * `teammateName`）。**它是个内部名，不该直接显示**——前缀那段是座位，渲染方拿它去查角色名。
   * 不是 Team 消息（真人、注入）时没有它。
   */
  readonly who?: string
  /** 正文。 */
  readonly text: string
}

/** 一次 splice 收下来的那一批。 */
export interface SaidBatch {
  /** 事件序号。 */
  readonly seq: number
  /** 这一批里的话，按进来的顺序。 */
  readonly lines: readonly SaidLine[]
}

declare module '@deepseek-ai/dsh-client-ui-chat/client' {
  interface ChatNodeDataMap {
    /** 房间页右栏读的就是它。 */
    'jubensha-said': SaidBatch
  }
}

/**
 * 剥掉 Team 消息自带的信封，**但把发信人留下来**。
 *
 * 玩家经 Team 的 `send_message` 发来的话，正文前面带着一段
 * `Team message <消息 id> from <成员名>: `——那是信道的记账，不是他说的话，所以正文要剥掉它。
 * 而**那个成员名是这一段里唯一能分辨"谁说的"的东西**：原先连它一起剥了，于是右栏只能笼统说
 * 「玩家」，四个座位分不出是哪一个（用户 2026-10-06 报的）。成员名的前缀就是座位 id。
 *
 * @param text - 原始正文。
 * @returns 剥掉信封的正文与发信人；没有信封时 `who` 为空。
 */
function unwrapTeamMessage(text: string): { text: string, who?: string } {
  const match = /^Team message \S+ from (\S+):\s*/u.exec(text)
  if (match === null) return { text }
  return { text: text.slice(match[0].length).trim(), who: match[1] }
}

/**
 * 把一条消息的 `content` 拍成一段文字。
 *
 * 它是富结构（`[{ type: 'text', text }]` 起头，还可能有别的东西），而房间页只要一句话。
 * 非文字的部分**不猜**——拍不出来就给空串，让调用方把这条丢掉。
 * @param content - 事件里的 `content` 字段。
 * @returns 拼起来的文字；没有文字内容时给空串。
 */
function textOf(content: unknown): { text: string, who?: string } {
  if (typeof content === 'string') return unwrapTeamMessage(content.trim())
  if (!Array.isArray(content)) return { text: '' }
  const parts: string[] = []
  for (const item of content) {
    if (typeof item === 'string') {
      parts.push(item)
      continue
    }
    if (typeof item !== 'object' || item === null) continue
    const one = item as { type?: unknown, text?: unknown }
    if (one.type === 'text' && typeof one.text === 'string') parts.push(one.text)
  }
  return unwrapTeamMessage(parts.join('\n').trim())
}

/**
 * 「谁说了什么」的投影定义。
 *
 * 每个 splice 一条 node（id 用事件序号），所以 `update` 直接回 `context.state` 就够——同一个
 * splice 不会被折叠第二次。
 */
export const saidDefinition: ConversationNodeDefinition<SaidBatch> = {
  kind: SAID_KIND,
  target: 'chat',
  match: event => event.type === 'agent/inbox/spliced'
    ? { id: String(event.seq), role: 'start' }
    : null,
  start: (_context, match) => {
    const event = match.event
    if (event.type !== 'agent/inbox/spliced') {
      throw new Error('jubensha-said: start requires agent/inbox/spliced')
    }
    const data = event.data as { inserted?: unknown }
    const inserted = Array.isArray(data.inserted) ? data.inserted : []
    const lines: SaidLine[] = []
    for (const item of inserted) {
      if (typeof item !== 'object' || item === null) continue
      const one = item as { content?: unknown, source?: { kind?: unknown } }
      const { text, who } = textOf(one.content)
      // 没有正文的丢掉：注入里有一大堆空的、或者只有工具调用的，它们不是"谁说了什么"。
      if (text === '') continue
      lines.push({
        seq: event.seq,
        from: typeof one.source?.kind === 'string' ? one.source.kind : '(没有来源)',
        ...(who === undefined ? {} : { who }),
        text,
      })
    }
    return { seq: event.seq, lines }
  },
  update: context => context.state,
  buildViewNode: (context) => {
    const start = context.start ?? context.matches[0]
    if (start === undefined || context.state === undefined) return null
    return {
      key: context.key,
      kind: SAID_KIND,
      id: context.id,
      target: 'chat',
      anchorSeq: start.event.seq,
      location: start.location,
      // 投影进得来，对话流里不出现——房间页有自己的渲染，不必在那儿多一行。
      visibility: 'hidden',
      data: context.state,
    } satisfies ChatNode<typeof SAID_KIND>
  },
}

/**
 * 右栏一次显示多少句。
 *
 * 右栏是"桌上说了什么"，不是全部历史——一局打下来几百句，全铺出来没人看。
 */
export const SAID_LIMIT = 40

/**
 * 一个 node 的 `data` 是不是我要的那一批。
 *
 * `ConversationViewNode.data` 的类型是 `unknown`——那是定义方与渲染方之间的边界，所以这里
 * 窄化一次，形状不对就当没看见（别让一个别的东西把右栏炸掉）。
 * @param data - node 上的 `data`。
 * @returns 认得出来就给那一批，否则给 `undefined`。
 */
function asBatch(data: unknown): SaidBatch | undefined {
  if (typeof data !== 'object' || data === null) return undefined
  const one = data as { seq?: unknown, lines?: unknown }
  if (typeof one.seq !== 'number' || !Array.isArray(one.lines)) return undefined
  return { seq: one.seq, lines: one.lines as SaidLine[] }
}

/**
 * 从会话快照里读「谁说了什么」。
 *
 * 走 `nodes.values()`——**全部已投影的 node**，一步到位：它不要求「哪几轮加载了」，也不要求
 * node 是可见的。这一点很关键：「团队」标签显示的时候对话页并没有在显示，那些轮可能根本不在
 * 导航索引里，而 `turnDataSource(turn, kind)` 是从导航索引拿 turn 的。
 *
 * 拿不到快照时给空数组——房间页那侧已经在轮询，这一格空着比整页报错好。
 * @param snapshot - Chat 目标的快照；目标还没就绪时给 `undefined`。
 * @returns 按时间序的句子，最多 `SAID_LIMIT` 条。
 */
export function readSaid(snapshot: ChatSnapshot | undefined): SaidLine[] {
  if (snapshot === undefined) return []
  const lines: SaidLine[] = []
  for (const node of snapshot.nodes.values()) {
    if (node.kind !== SAID_KIND) continue
    const batch = asBatch(node.data)
    if (batch === undefined) continue
    lines.push(...batch.lines)
  }
  // `values()` 明说"without imposing render order"，而每个 batch 内部的顺序是它自己的。
  // `Array.sort` 自 ES2019 起是稳定的，所以同一个 `seq` 里那几行不会被搅乱。
  lines.sort((left, right) => left.seq - right.seq)
  return lines.length > SAID_LIMIT ? lines.slice(lines.length - SAID_LIMIT) : lines
}
